mapper.select:
SELECT l.id, l.member_id, l.balance_type, l.change_type, l.before_amount, l.change_amount,
       l.after_amount, l.biz_no, u.nickname AS operator_name, l.remark, l.create_time
FROM salon_member_balance_log l
LEFT JOIN sys_user u ON u.id = l.operator_id AND u.deleted = 0

    l.deleted = 0

        AND l.member_id = #{q.memberId}


        AND l.store_id = #{q.storeId}


        AND l.balance_type = #{q.balanceType}


        AND l.change_type = #{q.changeType}


        AND l.create_time >= #{q.startTime}


        AND l.create_time <= #{q.endTime}


ORDER BY l.create_time DESC
